/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing
/// Controller class for automating the AMEX payment proposal process.
/// </summary>
class METAMEXCustPaymProposalController extends SysOperationServiceController
{
}

Method.Source:
    public static void main(Args args)
    {
        METAMEXCustPaymProposalController controller;

        controller = new METAMEXCustPaymProposalController();
        controller.parmArgs(args);
        controller.startOperation();
        
    }

public static METAMEXCustPaymProposalController construct()
{
    return new METAMEXCustPaymProposalController();
}

    /// <summary>
    /// Validates the service parameters as per business validations.
    /// </summary>
    /// <returns>true/fale</returns>
    protected boolean validate()
    {
        boolean     ret = true;
        #Define.ValidCompany(['8000','2002'])

        if (!conFind(#Validcompany, curExt()))
        {
            error("@MET:AMEXLegalEntityError");
            ret = false;
        }

        METAMEXCustPaymProposalContract   dataContract = this.getDataContractObject();

        if ((dataContract.parmRegion() == METAMEXRegion::AUS && dataContract.parmPaymentRun() == CustAccountStatement::AMEXNone)
            || (dataContract.parmRegion() == METAMEXRegion::NZL && dataContract.parmPaymentRun() != CustAccountStatement::AMEXNone))
        {
            error("@MET:AMEXParametersError");
            ret = false;
        }

        return ret;
    }
